package com.smartpricing.research;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class EvidenceQualityBenchmarkTest {
 @Test void observationalTwins(){for(long seed:new long[]{3101,4101,7101}){var a=EvidenceQualityFixtures.generate(EvidenceQualityFixtures.Kind.DISCRETE365,seed);var b=EvidenceQualityFixtures.generate(EvidenceQualityFixtures.Kind.HIDDEN_MARKETING,seed);assertThat(a.days()).isEqualTo(b.days());assertThat(a.beta()).isNotEqualTo(b.beta());assertThat(a.label()).isEqualTo("SAFE_ELIGIBLE");assertThat(b.label()).isEqualTo("UNSAFE");}}
 @Test void exportFrozenBenchmark()throws Exception{
 var helper=new OptimizerSafetyRegressionTest();StringBuilder diagnostics=new StringBuilder("split,scenario,seed,eligible,unknown,censored,zero,distinctPrices,minPrice,maxPrice,calendarR2,residualPriceSd,df,logRmse,uncertainty,backtestStatuses,backtestWape,backtestMae,cost,lowerBound,upperBound,reasons\n");StringBuilder csv=new StringBuilder("split,scenario,seed,n,hash,label,labelReason,coherent,trueBeta,status,price,oraclePrice,holdContribution,oracleContribution,regret,normalizedRegret,boundsCompliant,estimate,productionIntervalAvailable,waldLow,waldHigh,pairsLow,pairsHigh,blockLow,blockHigh,pairsValid,blockValid,waldShadow,blockShadow,reasons\n");
 var selected=EnumSet.of(EvidenceQualityFixtures.Kind.DISCRETE130,EvidenceQualityFixtures.Kind.DISCRETE180,EvidenceQualityFixtures.Kind.DISCRETE365,EvidenceQualityFixtures.Kind.DISCRETE700,EvidenceQualityFixtures.Kind.CONTINUOUS365,EvidenceQualityFixtures.Kind.HIDDEN_MARKETING,EvidenceQualityFixtures.Kind.STRUCTURAL,EvidenceQualityFixtures.Kind.NOISY,EvidenceQualityFixtures.Kind.ZERO_RESPONSE);
 for(String split:List.of("DEV","TEST","CHALLENGE")){long[] seeds=split.equals("DEV")?new long[]{3101,3103,3109,3119}:java.util.stream.LongStream.rangeClosed(split.equals("TEST")?4101:7101,split.equals("TEST")?4120:7112).toArray();for(long seed:seeds)for(var kind:EvidenceQualityFixtures.Kind.values()){
 var f=EvidenceQualityFixtures.generate(kind,seed);var market=helper.market(f.days(),f.missingCost());if(kind==EvidenceQualityFixtures.Kind.COST20||kind==EvidenceQualityFixtures.Kind.COST60||kind==EvidenceQualityFixtures.Kind.BOUNDARY)market=new com.smartpricing.optimization.repository.OptimizationRepository.Market(market.min(),market.max(),market.price(),java.math.BigDecimal.valueOf(f.trueCost()),market.priceFrom(),market.costFrom(),market.stock(),market.stockAt(),market.stockQuality());var r=helper.current.evaluate(helper.input(f.days()),market,30);var w=EvidenceQualityIntervals.wald(f.days());var a=selected.contains(kind)?EvidenceQualityIntervals.bootstrap(f.days(),seed+100000,1):null;var b=selected.contains(kind)?EvidenceQualityIntervals.bootstrap(f.days(),seed+200000,14):null;Double p=r.recommendedPrice()==null?null:Double.valueOf(r.recommendedPrice());double o=f.oracle(),oc=f.contribution(o);Double regret=p==null?null:oc-f.contribution(p);if(p!=null)assertThat(p).isBetween(f.lower()-1e-4,f.upper()+1e-4);
 var ready=r.elasticity().readiness();var id=r.elasticity().identification();diagnostics.append(LowDataBenchmarkTest.csv(split,kind,seed,ready.eligibleDays(),ready.unknownDays(),ready.censoredDays(),ready.zeroDays(),ready.distinctPrices(),ready.minPrice(),ready.maxPrice(),id==null?null:id.calendarPriceR2(),id==null?null:id.residualLogPriceSd(),id==null?null:id.residualDegreesOfFreedom(),r.elasticity().logRmse(),id==null?null:id.uncertaintyStatus(),r.backtests().stream().map(x->x.status()).toList(),r.backtests().stream().map(x->x.model()==null?null:x.model().wapePercent()).toList(),r.backtests().stream().map(x->x.model()==null?null:x.model().mae()).toList(),r.inputs().unitCost(),r.inputs().lowerBound(),r.inputs().upperBound(),String.join(";",r.reasons())));
 csv.append(LowDataBenchmarkTest.csv(split,kind,seed,f.days().size(),f.hash(),f.label(),f.labelReason(),f.coherent(),f.beta(),r.status(),p,o,f.contribution(100),oc,regret,regret==null||oc<=0?null:regret/oc,p==null?null:true,r.elasticity().estimate(),r.elasticity().confidenceLow()!=null&&r.elasticity().confidenceHigh()!=null,w==null?null:w.low(),w==null?null:w.high(),a==null?null:a.low(),a==null?null:a.high(),b==null?null:b.low(),b==null?null:b.high(),a==null?0:a.valid(),b==null?0:b.valid(),p!=null&&w!=null&&w.high()<0,p!=null&&b!=null&&b.high()<0,String.join(";",r.reasons())));
 }}Path out=Path.of(System.getProperty("evidence.output","target/evidence-quality"));Files.createDirectories(out);Files.writeString(out.resolve("cases.csv"),csv);Files.writeString(out.resolve("diagnostics.csv"),diagnostics);
 }
}
